import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { courseAPI, quizAPI } from '../api/api';
import { useAuth } from '../context/AuthContext';

export default function Dashboard() {
  const { user } = useAuth();
  const [enrollments, setEnrollments] = useState([]);
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(true);
  const [greeting, setGreeting] = useState('');

  useEffect(() => {
    const hour = new Date().getHours();
    setGreeting(hour < 12 ? '🌅 Good Morning' : hour < 17 ? '☀️ Good Afternoon' : '🌙 Good Evening');
    Promise.all([courseAPI.myEnrollments(), quizAPI.myResults()])
      .then(([eRes, qRes]) => { setEnrollments(eRes.data); setResults(qRes.data); })
      .finally(() => setLoading(false));
  }, []);

  const completed = enrollments.filter(e => e.status === 'COMPLETED').length;
  const avgScore = results.length
    ? Math.round(results.reduce((s, r) => s + r.percentage, 0) / results.length) : 0;
  const inProgress = enrollments.filter(e => e.status === 'IN_PROGRESS').length;

  if (loading) return (
    <div style={styles.loadingPage}>
      <div style={styles.spinner} />
      <p style={{ color:'rgba(255,255,255,0.4)', marginTop:16 }}>Loading your dashboard...</p>
    </div>
  );

  const stats = [
    { label:'Enrolled', value: enrollments.length, icon:'📚', color:'#e94560', bg:'rgba(233,69,96,0.1)' },
    { label:'In Progress', value: inProgress, icon:'⚡', color:'#f5a623', bg:'rgba(245,166,35,0.1)' },
    { label:'Completed', value: completed, icon:'🏆', color:'#16c79a', bg:'rgba(22,199,154,0.1)' },
    { label:'Avg Score', value: `${avgScore}%`, icon:'🎯', color:'#a29bfe', bg:'rgba(162,155,254,0.1)' },
  ];

  return (
    <div style={styles.page}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Syne:wght@600;700;800&family=DM+Sans:wght@300;400;500&display=swap');
        @keyframes fadeUp { from{opacity:0;transform:translateY(20px)} to{opacity:1;transform:translateY(0)} }
        @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.6} }
        .stat-card:hover { transform:translateY(-4px) !important; }
        .course-card:hover { transform:translateY(-3px) !important; border-color:rgba(233,69,96,0.4) !important; }
        .browse-btn:hover { background:rgba(233,69,96,0.2) !important; }
        .continue-btn:hover { opacity:0.85 !important; }
      `}</style>

      {/* Header */}
      <div style={styles.header}>
        <div>
          <p style={styles.greeting}>{greeting}</p>
          <h1 style={styles.name}>{user?.fullName} 👋</h1>
          <p style={styles.subtext}>Ready to learn something amazing today?</p>
        </div>
        <Link to="/courses" style={styles.exploreBtn}>Explore Courses →</Link>
      </div>

      {/* Stats */}
      <div style={styles.statsGrid}>
        {stats.map((s, i) => (
          <div key={i} className="stat-card" style={{...styles.statCard, animationDelay:`${i*0.1}s`}}>
            <div style={{...styles.statIcon, background: s.bg, color: s.color}}>{s.icon}</div>
            <div style={{...styles.statValue, color: s.color}}>{s.value}</div>
            <div style={styles.statLabel}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* My Courses */}
      <div style={styles.section}>
        <div style={styles.sectionHeader}>
          <h2 style={styles.sectionTitle}>My Courses</h2>
          <Link to="/courses" style={styles.seeAll}>Browse more →</Link>
        </div>

        {enrollments.length === 0 ? (
          <div style={styles.emptyState}>
            <div style={styles.emptyIcon}>📖</div>
            <p style={styles.emptyText}>You haven't enrolled in any courses yet</p>
            <Link to="/courses" className="browse-btn" style={styles.browseBtn}>Browse Courses</Link>
          </div>
        ) : (
          <div style={styles.courseGrid}>
            {enrollments.map((e, i) => (
              <div key={e.id} className="course-card" style={{...styles.courseCard, animationDelay:`${i*0.08}s`}}>
                {/* Color bar */}
                <div style={{...styles.colorBar, background: e.status==='COMPLETED'
                  ? 'linear-gradient(90deg,#16c79a,#0ea87f)'
                  : 'linear-gradient(90deg,#e94560,#c62a47)'}} />

                <div style={styles.courseBody}>
                  <div style={styles.courseBadge}>
                    {e.status === 'COMPLETED'
                      ? <span style={{...styles.badge, background:'rgba(22,199,154,0.15)', color:'#16c79a'}}>✅ Completed</span>
                      : <span style={{...styles.badge, background:'rgba(245,166,35,0.15)', color:'#f5a623'}}>⚡ In Progress</span>}
                  </div>
                  <div style={styles.courseTitle}>{e.courseTitle}</div>
                  <div style={styles.enrollDate}>Enrolled: {e.enrolledAt}</div>

                  {/* Progress */}
                  <div style={styles.progressSection}>
                    <div style={styles.progressTop}>
                      <span style={styles.progressLabel}>Progress</span>
                      <span style={styles.progressPct}>{e.progressPercent}%</span>
                    </div>
                    <div style={styles.progressTrack}>
                      <div style={{
                        ...styles.progressFill,
                        width: `${e.progressPercent}%`,
                        background: e.status==='COMPLETED'
                          ? 'linear-gradient(90deg,#16c79a,#0ea87f)'
                          : 'linear-gradient(90deg,#e94560,#f5a623)'
                      }} />
                    </div>
                  </div>

                  <Link to={`/courses/${e.courseId}`} className="continue-btn" style={styles.continueBtn}>
                    {e.status === 'COMPLETED' ? 'Review Course' : 'Continue Learning'} →
                  </Link>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Quiz Results */}
      {results.length > 0 && (
        <div style={styles.section}>
          <div style={styles.sectionHeader}>
            <h2 style={styles.sectionTitle}>Quiz Results</h2>
            <span style={styles.resultCount}>{results.length} attempts</span>
          </div>
          <div style={styles.resultsTable}>
            <div style={styles.tableHead}>
              <span>Quiz Name</span>
              <span>Score</span>
              <span>Percentage</span>
              <span>Status</span>
            </div>
            {results.map((r, i) => (
              <div key={r.resultId} style={{...styles.tableRow, animationDelay:`${i*0.05}s`}}>
                <span style={styles.quizName}>{r.quizTitle}</span>
                <span style={styles.quizScore}>{r.score}/{r.total}</span>
                <div style={styles.pctBar}>
                  <div style={{
                    ...styles.pctFill,
                    width:`${r.percentage}%`,
                    background: r.percentage>=60 ? '#16c79a' : '#e94560'
                  }}/>
                  <span style={{...styles.pctText, color: r.percentage>=60 ? '#16c79a' : '#e94560'}}>
                    {r.percentage.toFixed(1)}%
                  </span>
                </div>
                <span style={{
                  ...styles.statusBadge,
                  background: r.percentage>=60 ? 'rgba(22,199,154,0.15)' : 'rgba(233,69,96,0.15)',
                  color: r.percentage>=60 ? '#16c79a' : '#e94560'
                }}>
                  {r.percentage>=60 ? '🎉 Passed' : '❌ Failed'}
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  page: { maxWidth:1100, margin:'0 auto', padding:'36px 28px', fontFamily:"'DM Sans',sans-serif", animation:'fadeUp 0.5s ease' },
  loadingPage: { minHeight:'60vh', display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center' },
  spinner: { width:40, height:40, border:'3px solid rgba(233,69,96,0.2)', borderTop:'3px solid #e94560', borderRadius:'50%', animation:'spin 0.8s linear infinite' },

  header: { display:'flex', alignItems:'flex-end', justifyContent:'space-between', marginBottom:36, flexWrap:'wrap', gap:16 },
  greeting: { color:'rgba(255,255,255,0.4)', fontSize:13, margin:'0 0 4px', fontWeight:500 },
  name: { fontFamily:"'Syne',sans-serif", fontSize:32, fontWeight:800, color:'#fff', margin:'0 0 6px' },
  subtext: { color:'rgba(255,255,255,0.35)', fontSize:14, margin:0 },
  exploreBtn: { padding:'12px 24px', background:'linear-gradient(135deg,#e94560,#c62a47)', color:'#fff', borderRadius:12, textDecoration:'none', fontWeight:600, fontSize:14, whiteSpace:'nowrap' },

  statsGrid: { display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(200px,1fr))', gap:16, marginBottom:36 },
  statCard: { background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:16, padding:'24px 20px', backdropFilter:'blur(10px)', transition:'transform 0.2s ease', animation:'fadeUp 0.5s ease both', cursor:'default' },
  statIcon: { width:44, height:44, borderRadius:12, display:'flex', alignItems:'center', justifyContent:'center', fontSize:20, marginBottom:14 },
  statValue: { fontSize:34, fontWeight:700, fontFamily:"'Syne',sans-serif", lineHeight:1 },
  statLabel: { color:'rgba(255,255,255,0.4)', fontSize:13, marginTop:6 },

  section: { marginBottom:36 },
  sectionHeader: { display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:18 },
  sectionTitle: { fontFamily:"'Syne',sans-serif", color:'#fff', fontSize:20, fontWeight:700, margin:0 },
  seeAll: { color:'#e94560', textDecoration:'none', fontSize:13, fontWeight:600 },
  resultCount: { color:'rgba(255,255,255,0.3)', fontSize:13 },

  emptyState: { background:'rgba(255,255,255,0.03)', border:'1px dashed rgba(255,255,255,0.1)', borderRadius:16, padding:'48px 24px', textAlign:'center' },
  emptyIcon: { fontSize:48, marginBottom:12 },
  emptyText: { color:'rgba(255,255,255,0.35)', marginBottom:20 },
  browseBtn: { display:'inline-block', padding:'10px 24px', border:'1px solid rgba(233,69,96,0.4)', color:'#e94560', borderRadius:10, textDecoration:'none', fontSize:14, fontWeight:600, transition:'all 0.2s' },

  courseGrid: { display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(300px,1fr))', gap:16 },
  courseCard: { background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:16, overflow:'hidden', transition:'all 0.2s ease', animation:'fadeUp 0.5s ease both', backdropFilter:'blur(10px)' },
  colorBar: { height:4 },
  courseBody: { padding:20 },
  courseBadge: { marginBottom:10 },
  badge: { padding:'4px 12px', borderRadius:20, fontSize:12, fontWeight:600 },
  courseTitle: { fontFamily:"'Syne',sans-serif", color:'#fff', fontWeight:700, fontSize:16, marginBottom:6, lineHeight:1.4 },
  enrollDate: { color:'rgba(255,255,255,0.3)', fontSize:12, marginBottom:16 },
  progressSection: { marginBottom:16 },
  progressTop: { display:'flex', justifyContent:'space-between', marginBottom:8 },
  progressLabel: { color:'rgba(255,255,255,0.4)', fontSize:12 },
  progressPct: { color:'#fff', fontSize:12, fontWeight:600 },
  progressTrack: { height:6, background:'rgba(255,255,255,0.08)', borderRadius:20, overflow:'hidden' },
  progressFill: { height:'100%', borderRadius:20, transition:'width 0.5s ease' },
  continueBtn: { display:'block', textAlign:'center', padding:'10px', background:'rgba(233,69,96,0.15)', border:'1px solid rgba(233,69,96,0.3)', color:'#e94560', borderRadius:10, textDecoration:'none', fontSize:13, fontWeight:600, transition:'opacity 0.2s' },

  resultsTable: { background:'rgba(255,255,255,0.03)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:16, overflow:'hidden' },
  tableHead: { display:'grid', gridTemplateColumns:'1fr 80px 160px 100px', gap:16, padding:'12px 20px', background:'rgba(255,255,255,0.04)', color:'rgba(255,255,255,0.35)', fontSize:12, fontWeight:600, textTransform:'uppercase', letterSpacing:'0.05em' },
  tableRow: { display:'grid', gridTemplateColumns:'1fr 80px 160px 100px', gap:16, padding:'14px 20px', borderTop:'1px solid rgba(255,255,255,0.05)', alignItems:'center', animation:'fadeUp 0.4s ease both' },
  quizName: { color:'#fff', fontSize:14, fontWeight:500 },
  quizScore: { color:'rgba(255,255,255,0.6)', fontSize:14 },
  pctBar: { display:'flex', alignItems:'center', gap:10 },
  pctFill: { height:6, borderRadius:20, flex:1, maxWidth:80 },
  pctText: { fontSize:13, fontWeight:600, minWidth:40 },
  statusBadge: { padding:'4px 10px', borderRadius:20, fontSize:11, fontWeight:600, textAlign:'center' },
};
